import json
from pathlib import Path
j=json.loads(Path('benchmark/source_data.json').read_text())
# Build 2024 values
vals={}
for row in j['external_debt_to_gdp']['data']:
  if row['year']==2024:
    vals.setdefault(row['country'],{})['debt']=row['debt_gdp_pct']
for row in j['currency_depreciation']['data']:
  if row['year']==2024:
    vals.setdefault(row['country'],{})['dep']=row['depreciation_pct']
# count downgrades 2022-2023
from collections import defaultdict
cnt=defaultdict(int)
for r in j['sovereign_rating_changes']['data']:
  y=int(r['date'][:4])
  if r['action'] in ('downgrade','default') and y in (2022,2023):
    cnt[r['country']]+=1
for c in vals:
  vals[c]['downg_22_23']=cnt[c]
# print sorted by dep
for c,v in sorted(vals.items(), key=lambda kv: kv[1]['dep'], reverse=True):
  print(c,v)
