import json
from pathlib import Path
j=json.loads(Path('benchmark/source_data.json').read_text())
# assemble 2024 debt & depreciation
countries=sorted({r['country'] for r in j['external_debt_to_gdp']['data']})
vals={c:{'debt':None,'dep':None} for c in countries}
for r in j['external_debt_to_gdp']['data']:
  if r['year']==2024:
    vals[r['country']]['debt']=r['debt_gdp_pct']
for r in j['currency_depreciation']['data']:
  if r['year']==2024:
    vals[r['country']]['dep']=r['depreciation_pct']
# count stress actions during 2022-2023 (downgrade+default)
from collections import defaultdict
stress=defaultdict(int)
for r in j['sovereign_rating_changes']['data']:
  y=int(r['date'][:4])
  if y in (2022,2023) and r['action'] in ('downgrade','default'):
    stress[r['country']]+=1
for c in countries:
  vals[c]['stress']=stress[c]
# prepare output
print(countries)
print(vals)
PY

